// Verify the HMAC-SHA256 signature ControlHub sends in X-ControlHub-Signature.
// ControlHub signs json.dumps(payload, separators=(',',':')) with N8N_WEBHOOK_SECRET.
const crypto = require('crypto');
const item = $input.first().json;
const secret = $env.N8N_WEBHOOK_SECRET || '';
const sig = (item.headers && (item.headers['x-controlhub-signature'] || item.headers['X-ControlHub-Signature'])) || '';
const raw = JSON.stringify(item.body);
if (secret) {
  const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
  if (expected !== sig) {
    throw new Error('Invalid ControlHub signature — rejecting event');
  }
}
return [{ json: item.body }];

